import{_ as t,o,c as r,ag as a}from"./chunks/framework.B7PviQjB.js";const s="/docs/images/slides/present-slideshow-menu.png",m=JSON.parse('{"title":"Present a deck","description":"Write speaker notes, present a deck full screen, and download it as PowerPoint or PDF.","frontmatter":{"title":"Present a deck","description":"Write speaker notes, present a deck full screen, and download it as PowerPoint or PDF.","type":"how-to"},"headers":[],"relativePath":"slides/present.md","filePath":"slides/present.md"}'),n={name:"slides/present.md"};function i(d,e,l,h,c,p){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="present-a-deck" tabindex="-1">Present a deck <a class="header-anchor" href="#present-a-deck" aria-label="Permalink to &quot;Present a deck&quot;">​</a></h1><p>Write speaker notes for each slide, present the deck full screen, and download a copy to share or present elsewhere.</p><h2 id="write-speaker-notes" tabindex="-1">Write speaker notes <a class="header-anchor" href="#write-speaker-notes" aria-label="Permalink to &quot;Write speaker notes&quot;">​</a></h2><ol><li>Open the slide.</li><li>Click the <strong>Speaker notes…</strong> box below the canvas and type.</li></ol><p>Notes save as you type and stay with their slide. A collaborator&#39;s changes to the notes appear as they make them.</p><p>To make the notes box taller or shorter, drag the divider above it. Your browser remembers the size.</p><h2 id="start-a-slideshow" tabindex="-1">Start a slideshow <a class="header-anchor" href="#start-a-slideshow" aria-label="Permalink to &quot;Start a slideshow&quot;">​</a></h2><ol><li>Open the slide you want to start from.</li><li>Click <strong>Slideshow</strong> in the header. The deck fills the screen.</li></ol><p>To start from the first slide, click the arrow next to <strong>Slideshow</strong> (<strong>Present options</strong>) and select <strong>Present from beginning</strong>.</p><p>You can also press <code>⌘+Enter</code> / <code>Ctrl+Enter</code> to present from the current slide, or <code>⌘+Shift+Enter</code> / <code>Ctrl+Shift+Enter</code> to present from the beginning.</p><p><img src="'+s+'" alt="Slideshow button with the Present options menu open, showing Present from current slide and Present from beginning"></p><h3 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h3><p>Tap the play button (<strong>Slideshow</strong>) in the header to present from the current slide. To start from the first slide, tap the ⋮ button in the header (<strong>More</strong>) and select <strong>Present from beginning</strong>. Tap or swipe to move between slides.</p><h2 id="move-between-slides" tabindex="-1">Move between slides <a class="header-anchor" href="#move-between-slides" aria-label="Permalink to &quot;Move between slides&quot;">​</a></h2><p>Each step forward plays the next <strong>On Click</strong> animation, then moves to the next slide.</p><table tabindex="0"><thead><tr><th>To do this</th><th>Keyboard</th><th>Mouse or touch</th></tr></thead><tbody><tr><td>Go forward</td><td><code>→</code>, <code>Space</code>, <code>Page Down</code>, or <code>N</code></td><td>Click, tap the right two-thirds of the screen, or swipe left</td></tr><tr><td>Go back</td><td><code>←</code>, <code>Backspace</code>, <code>Page Up</code>, or <code>P</code></td><td>Tap the left third of the screen, or swipe right</td></tr><tr><td>Go to the first slide</td><td><code>Home</code></td><td></td></tr><tr><td>Go to the last slide</td><td><code>End</code></td><td></td></tr><tr><td>Leave the slideshow</td><td><code>Escape</code></td><td></td></tr></tbody></table><p>The pointer hides after three seconds without movement. Move the mouse to show it again.</p><h2 id="end-the-slideshow" tabindex="-1">End the slideshow <a class="header-anchor" href="#end-the-slideshow" aria-label="Permalink to &quot;End the slideshow&quot;">​</a></h2><p>Press <code>Escape</code> at any time to return to the editor. After the last slide, a screen reads <strong>End of slideshow — click or press Esc to exit</strong>. Click it or press <code>Escape</code>.</p><h2 id="download-the-deck" tabindex="-1">Download the deck <a class="header-anchor" href="#download-the-deck" aria-label="Permalink to &quot;Download the deck&quot;">​</a></h2><ol><li>Click <strong>Export</strong> (the download icon) in the header.</li><li>Select <strong>PowerPoint (.pptx)</strong> or <strong>PDF (.pdf)</strong>.</li></ol><p>A progress message appears while the file is prepared, then your browser downloads it. On a phone, the export options are under <strong>Export</strong> in the header&#39;s ⋮ (<strong>More</strong>) menu.</p><p>PowerPoint files keep your speaker notes. PDF files have one page per slide. See <a href="/docs/files/import-export.html">Import and export</a> for what each format keeps.</p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>Speaker notes are plain text, with no bold, italic, or lists.</li><li>People who open the deck through a share link have no <strong>Slideshow</strong> or <strong>Export</strong> button.</li><li>There is no presenter view. Speaker notes don&#39;t show while you present.</li><li>Speaker notes aren&#39;t available on a phone.</li><li>If two people type in the same notes box at once, one person&#39;s typing can overwrite the other&#39;s.</li><li>Each PDF page is an image of the slide, so its text can&#39;t be selected or searched, and notes aren&#39;t included.</li><li>A PowerPoint export leaves out charts that came from an imported PowerPoint file, without a warning. Keep the original file if you need them.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/slides/animations.html">Animations and transitions</a> to control what happens on each click.</li><li><a href="/docs/slides/keyboard-shortcuts.html">Keyboard shortcuts</a> for every slideshow key.</li><li><a href="/docs/collaborate/share.html">Share a document</a> to send a link instead of a file.</li></ul>',27)])])}const f=t(n,[["render",i]]);export{m as __pageData,f as default};
